;w InvNo_"^"_Flag_"^"_PrtFlag
if ((InvNo="")&(Flag="N")&(PrtFlag'="P")) ! ((InvNo'="")&(Flag="N")&(PrtFlag="P")) ! ((InvNo="")&(Flag="N")&(accPINVDR'="")) {
	if (User'=UserRowId) {
		s Status="S"
