if SecheduleDate="" {
	s SecheduleDate=..%SysDate()
}else {
	i $l(SecheduleDate,"-")=3 s SecheduleDate=$zdh(SecheduleDate,3)
	i $l(SecheduleDate,"/")=3 s SecheduleDate=$zdh(SecheduleDate,4)
}
