i AvailAS'="" {
	s DefaultTimeRangeRowId=##class(web.DHCRBResSession).GetTimeRangeByTime(..%SysTime())
	if (DefaultTimeRangeRowId'="") {
		for i=1:1:$l(AvailAS,"^") {
