q:AppDate=""||Type="" ""
Set AdmDate=..%ZDH(AppDate)
set Today=..%SysDate()+1
if (Type="Now"){
	s limit=$zd(Today,10)
	s now=Today
	s NewtNow=Today+7-limit
}elseif(Type="Next"){
	s limit=$zd(AdmDate,10)
	s now=AdmDate+8-limit
	s NewtNow=now+7
}elseif(Type="Before"){
	s limit=$zd(AdmDate,10)
	if (limit=0) s limit=7
	s NewtNow=AdmDate-limit
	s now=NewtNow-6
	if (now<Today) {
		s now=Today
		s limit=$zd(Today,10)
		s NewtNow=Today+7-limit
	}
} 
s textdate=..%ZD(now)
q textdate_"^"_now_"^"_NewtNow

